(window.VOCAB_EXAMPLES_UZ = window.VOCAB_EXAMPLES_UZ || {})["0123"] = {
  "장래": ["Kelajakdagi orzuim shifokor bo'lish.", "Kelajakda kim bo'lmoqchisan?", "Farzandimning kelajagini o'ylab, yaxshi maktab tanladim.", "O'smirlarning kelajakdagi orzulari jamiyatdagi kayfiyat va iqtisodiy vaziyatdan katta ta'sirlanadi.", "U kelajagi porloq yosh olim sifatida ilmiy jamoatchilik e'tiborida.", "Juda olis kelajakni ham o'ylab, u bugun ham jimgina urug' sepdi."],
  "장례식": ["Bugun dafn marosimiga boraman.", "Bobomning dafn marosimiga barcha qarindoshlar yig'ildi.", "Dafn marosimida odatda qora kiyim kiyiladi va jimgina hamdardlik bildiriladi.", "So'nggi paytlarda dafn marosimini sodda tarzda o'tkazishni istovchilar tobora ko'payib bormoqda.", "Dafn marosimi davomida u ko'z yoshlarini ichiga yutib, olamdan o'tgan do'stining surati yonidan bir qadam ham jilmadi.", "Dafn marosimidagi tutatqi hidi ichida biz hayot va o'lim naqadar yaqin ekanini yana bir bor angladik."],
  "장례식장": ["Motam zali qayerda?", "Motam zaligacha taksida bordim.", "Shifoxona yonidagi motam zalida oila a'zolari mehmonlarni kutib olishdi.", "Har bir yirik shifoxonada motam zali bo'lgani uchun marhumning yaqinlari undan qulay foydalanishi mumkin.", "Motam zali kiraverishida ta'ziyaga kelganlar qoldirgan oq xrizantemalar tartib bilan terib qo'yilgan edi.", "Kech tungacha chirog'i o'chmagan motam zalida faqat marhumni xotirlayotgan past ovozlar aylanib yurardi."],
  "장바구니": ["Xarid savatini olib keldim.", "Xarid savatiga olma va sut soldim.", "Selofan paket o'rniga xarid sumkasidan foydalansangiz, atrof-muhitga foyda bo'ladi.", "Onlayn do'konda savatga solib qo'ygan mahsulotim sotilib tugagani uchun afsuslandim.", "Bozor savatchasi narxlari degan ibora ko'rsatib turganidek, oddiy xalq oziq-ovqat narxlari o'zgarishiga sezgir bo'lmay iloji yo'q.", "Eski xarid savatini sabzavotga to'ldirib olib kelgan onamning qiyofasi hamon ko'z o'ngimda turibdi."],
  "장사": ["Savdo yaxshi ketyapti.", "Otam bozorda savdo qiladilar.", "U kishi shu kunlarda mijoz yo'qligi sababli savdo yurishmayotganini aytdilar.", "U savdo-sotiqni kichik do'kondan boshlab, o'n yil ichida katta restoran ochdi.", "Iqtisodiy ahvol yomonlashgach, savdo ishini yig'ishtirib, boshqa ish izlayotgan kichik tadbirkorlar keskin ko'paydi.", "Savdo faqat foyda ortidan quvish emas, balki odamlar ishonchini to'plab borish ishidir, dedi chol."],
  "장애": ["U bolaning nogironligi bor.", "Nogironligi bo'lsa ham, astoydil yashaydi.", "U eshitish nuqsonini yengib, ajoyib musiqachiga aylandi.", "Nutqida nuqsoni bor odamlar uchun yangi ta'lim dasturi ishlab chiqildi.", "Hech qanday to'siq irodani sindira olmasligini uning hayoti isbotlab berdi.", "Tanadagi nuqsondan ham dahshatlirog'i qalbda to'plangan xurofot to'sig'idir, dedi ayol vazminlik bilan."],
  "장애인": ["Bu yer nogironlar uchun to'xtash joyi.", "Nogironlar uchun lift bor.", "Har bir metro bekatida imkoniyati cheklangan odamlar uchun qulay sharoitlar ko'paytirilmoqda.", "Hukumat nogironlarni ishga joylashtirishni ko'paytirish maqsadida kompaniyalarga turli yordam ko'rsatmoqda.", "Nogironligi bo'lgan shaxslarning erkin harakatlanish huquqini ta'minlash oddiy ijtimoiy yordam emas, balki asosiy inson huquqlari masalasidir.", "Nogironlarga achinish obyekti sifatida emas, balki teng huquqli qo'shnilar sifatida qaraganimizdagina jamiyat chinakam yetuklashadi."],
  "장학": ["Stipendiya tizimi bor.", "Maktabimizda stipendiya imtiyozlari ko'p.", "O'sha jamg'arma stipendiya dasturi orqali muhtoj talabalarga yordam beradi.", "Universitet a'lo baholarga o'qiydigan talabalarni saralab, stipendiya dasturiga tavsiya qildi.", "Mahalliy jamoaning stipendiya jamg'armasi tufayli ko'plab talabalar o'qishni tashlamay davom ettira oldi.", "U talabalik yillarida olgan stipendiyasi yordamini unutmay, keyinchalik o'zidan keyingi talabalar uchun shaxsiy mablag'ini ayamay ehson qildi."],
  "장학금": ["Stipendiya oldim.", "Stipendiyaga ariza qachongacha topshiriladi?", "Astoydil o'qiganim uchun bu semestrda stipendiya oladigan bo'ldim.", "Bu universitet a'lo o'qiydigan chet ellik talabalarga to'liq stipendiya to'laydi.", "Stipendiya olgan talabalar o'qishni bitirgach, jamiyatga qaytarib berish niyatini bildirishdi.", "U qashshoqlikda ham bitta stipendiyaga tayanib, orzusidan voz kechmadi va nihoyat fan doktori bo'ldi."],
  "재발급": ["Kartani qayta berib yuboring.", "Pasportni qayta olish qancha vaqt oladi?", "Hamyonimni yo'qotib qo'yganim uchun shaxsiy guvohnomani qayta olishim kerak.", "Bankka shaxsni tasdiqlovchi hujjatni olib borsangiz, yo'qotilgan debet kartani darhol qayta rasmiylashtirib olishingiz mumkin.", "Ma'lumotnomalarni qayta berish tartibi onlayn soddalashtirilgach, murojaat qiluvchilarning noqulayliklari ancha kamaydi.", "Ma'lumotlarni o'g'irlash holatlari ketma-ket sodir bo'lgach, rasmiylar sertifikatni qayta berishda shaxsni tasdiqlashni yanada qat'iylashtirishga qaror qildi."],
  "재산": ["Uning boyligi ko'p.", "Sog'liq eng katta boylik.", "Ota-onamiz bizga ko'p mol-mulk qoldirmadilar.", "O'sha tadbirkor boyligining yarmini jamiyatga xayriya qilishga ochiq va'da berdi.", "Meros mulki yuzasidan oila a'zolari o'rtasidagi nizolarning sudgacha borib yetishi holatlari oz emas.", "Pul bilan o'lchab bo'lmaydigan do'stlar bilan bog'liq xotiralar umrbod saqlanadigan eng qimmatli boylik edi."],
  "재작년": ["Ikki yil oldin Koreyaga keldim.", "Ikki yil oldingi yoz juda issiq edi.", "O'tgan yildan oldingi yili turmush qurdim, hozir bitta farzandim bor.", "Ikki yil oldingi bilan solishtirganda, bu yilgi eksport hajmi sezilarli darajada oshgani ma'lum bo'ldi.", "U o'tgan yildan oldingi yili katta jarrohlik operatsiyasini boshdan kechirgach, turmush tarzini butunlay o'zgartirganini aytishadi.", "Ikki yil oldin ayni shu paytlarda birga yurgan so'qmoqdan yolg'iz yurganimda, sog'inch xazondek to'planib bordi."],
  "재주": ["U juda iste'dodli.", "Ukamning qo'shiq aytish iste'dodi bor.", "U bolaning rasm chizish iste'dodi zo'r bo'lgani uchun ko'p mukofotlar ham olgan.", "Faqat iste'dodga ishonib, harakat qilmasangiz, oxir-oqibat tinimsiz mehnat qilgan odamni yenga olmaysiz.", "U o'zgacha iste'dod bilan tug'ilgan bo'lsa ham, o'zini tinimsiz takomillashtirishdan erinmasdi.", "Iste'dodli kishilar qashshoqlikdan qutula olmaydigan zamona zayli haqida qadimgi shoir uzun nola qoldirgan."],
  "재즈": ["Men jazni yaxshi ko'raman.", "Jaz musiqasini tinglab qahva ichaman.", "Har dam olish kunlari jaz kafega borib, jonli ijroni tomosha qilaman.", "Bu shaharda har yili kuzda xalqaro jaz festivali o'tkazilib, ko'plab tomoshabinlar yig'iladi.", "Uning ijrosi an'anaviy jazning bedahaligiga zamonaviy ruhni qo'shib, tanqidchilarning olqishiga sazovor bo'ldi.", "Chuqur tunda past ohangda taralgan jaz kuyi kun charchog'ini silab-siypab, shaharni asta-sekin uxlatdi."],
  "재테크": ["Men pulni ko'paytirish usullariga qiziqaman.", "Shu kunlarda pulni ko'paytirish haqidagi kitoblarni o'qiyapman.", "Maoshni tejab, jamg'arma hisobiga qo'yish ham pulni ko'paytirishning yaxshi usuli.", "Yosh xodimlar orasida aksiyalar va investitsiya fondlari orqali pulni ko'paytirish keng urf bo'lmoqda.", "Haddan tashqari tavakkalli investitsiyalar aksincha katta zararga olib kelishi mumkin, shuning uchun ehtiyotkorona qaror qabul qilish talab etiladi.", "Pulni ko'paytirish ishtiyoqi avj olgan zamonda odamlar faqat pulni ko'paytirishni o'rganib, uni sarflashni esa unutib bormoqdalar."],
  "재학": ["Men universitetda o'qiyman.", "O'qish davomida yarim kunlik ishda ishladim.", "O'qish davomida to'garak faoliyatida faol qatnashdim.", "Hozir o'qiyotgan talabalar ham, bitiruvchilar ham bu kutubxonadan bepul foydalanishi mumkin.", "O'qish yillaridagi tajribasi uning kasb tanlashiga hal qiluvchi ta'sir ko'rsatdi.", "O'qish yillarida birga tunlarni bedor o'tkazib bahslashgan do'stlar endi har biri o'z o'rnida dunyoni boshqarmoqda."],
  "재해": ["Bu yil ofatlar ko'p bo'ldi.", "To'fon katta ofatga sabab bo'ladi.", "Zilzila kabi tabiiy ofat yuz bersa, xotirjamlik bilan xavfsiz joyga chiqib ketish kerak.", "Hukumat tabiiy ofat yuz bergan hudud aholisi uchun shoshilinch tiklash mablag'larini ajratishga qaror qildi.", "Iqlim o'zgarishi tufayli kuchli jala kabi tabiiy ofatlar yildan-yilga ko'lamini kengaytirib bormoqda.", "Ofat vayron qilib o'tgan xarobalar ustida ham odamlar bir-birining qo'lidan tutib, yana oyoqqa turmoqda edi."],
  "재혼": ["U kishi qayta turmush qurdi.", "Otam qayta uylanib, o'gay onam paydo bo'ldi.", "Ajrashganidan bir necha yil o'tib, u yaxshi odamni uchratib, qayta turmush qurdi.", "Qayta turmush qurgan oilalardagi bolalar duch keladigan qiyinchiliklarni kamaytirish maqsadida psixologik maslahat yordami kengaytirilmoqda.", "Qayta turmush qurishga nisbatan jamiyat qarashlari o'tmishdagiga qaraganda ancha bag'rikeng bo'lgani haqida so'rov natijalari e'lon qilindi.", "Ikkinchi muhabbatni tanlab, qayta turmush qurish yo'lida ular bir-birining jarohatlarini so'zsiz bag'riga bosdilar."],
  "재활용": ["Qayta ishlanadigan chiqindilarni tashlayman.", "Qog'ozni qayta ishlash mumkin.", "Bizning mahallada haftada bir marta qayta ishlanadigan chiqindilar saralab yig'iladi.", "PET shishalarni qayta ishlab kiyim tayyorlaydigan kompaniyalar ko'payishi bilan atrof-muhitni muhofaza qilishga bo'lgan qiziqish ortdi.", "Resurslarni qayta ishlash tizimi tartibga solinmasa, chiqindi muammosi kelgusida yanada jiddiylashadi.", "Tashlab yuborilgan narsalarga yangi jon ato etuvchi qayta ishlash Yer bilan tuzilgan oddiy, ammo hayotiy ahddir."],
  "재활용품": ["Qayta ishlanadigan buyumlarni shu yerga tashlang.", "Qayta ishlanadigan buyumlarni yig'ib, tashqariga chiqarib qo'ydim.", "Shisha idishlar va bankalar kabi qayta ishlanadigan buyumlarni turlariga ajratib tashlash kerak.", "Shahar hokimiyati aholining ishtirokini oshirish maqsadida qayta ishlanadigan chiqindilarni yig'ish usulini o'zgartirmoqchi.", "Qayta ishlanadigan buyumlar to'g'ri saralab tashlanmasa, aksincha qayta ishlash darajasi pasayadi.", "U eski qayta ishlanadigan buyumlar uyumidan yangi foyda topish ishiga butun umri davomida ishtiyoq bag'ishladi."],
  "쟤": ["Anavi kim?", "Anavi mening do'stim.", "Anavi bola doim jilmayib yuradi, shuning uchun u bilan birga bo'lsam kayfiyatim ko'tariladi.", "Anavi bola yana uy vazifasini qilmay kelibdi, o'qituvchiga nima deb aytsam ekan?", "Anavi bolaga qara, shunchalik yosh bo'lsa ham kattalardek ukasiga g'amxo'rlik qilyapti-ku.", "Anavi bola shunchalik shaddod bo'lib ko'rinsa-da, ichi hammadan teranroq ekanini men allaqachon bilardim."],
  "저금": ["Men har oy pul jamg'araman.", "Jamg'argan pulimga sovg'a sotib oldim.", "Cho'ntak pulimni tejab, bankka jamg'arish odatini shakllantirdim.", "Yoshlikdan muntazam pul jamg'arish odatini shakllantirsa, iqtisodiy tushuncha tabiiy ravishda paydo bo'ladi.", "U isrofgarchilikdan yiroq yurib, maoshining yarmini jamg'ardi va nihoyat kichik bir uy sotib oldi.", "Tiyinma-tiyin yig'ilgan jamg'arma keyinchalik uning orzusini ko'tarib turgan mustahkam ustunga aylandi."],
  "저금통": ["Cho'chqachaga tanga solaman.", "Pul yig'adigan qutim to'lib qoldi.", "Bola cho'chqachani ochib, yig'gan pullarini sanab ko'rdi.", "Cho'chqa shaklidagi jamg'arma qutisiga tanga yig'ib, muhtoj qo'shnilarga yordam beradigan o'quvchilar ko'paymoqda.", "Jamg'arma qutisini sindirgan lahzada shu paytgacha sabr bilan o'tkazilgan vaqtlar birdaniga to'kilib ketgandek bo'ldi.", "Tortma ichida unutilib yotgan eski pul yig'ish qutisida bolalikning sodda orzulari butunligicha saqlanib qolgan edi."],
  "저렴하다": ["Bu kiyim arzon.", "Narxi arzon bo'lgani uchun sotib oldim.", "Bozorda mevalarni arzon olish mumkin, shuning uchun u yerga tez-tez boraman.", "Bu oshxona narxi arzon bo'lishiga qaramay, ta'mi ham, porsiyasi ham a'lo bo'lgani uchun talabalar orasida juda mashhur.", "Aviachiptani arzonga olish uchun mavsum cho'qqisidan qochib, oldindan bron qilgan ma'qul.", "Arzon narxga uchib, sifatiga qaramay xarid qilaverganingda, oxir-oqibat yanada kattaroq bahoni to'laysan."],
  "저울": ["Tarozi qayerda?", "Tarozida olmaning og'irligini o'lchayman.", "Do'kon egasi go'shtni taroziga qo'yib, aniq tortib berdi.", "Bu tarozi og'irlikdagi eng kichik farqni ham aniq o'lchay oladigan qilib yasalgan.", "Adolat ma'budasi qo'lidagi tarozi hech bir tomonga og'maydigan xolis hukmning ramzidir.", "Vijdon tarozisiga qo'yib qaralsa, uning bahonalari bir hovuch changdan ham yengil edi, xolos."],
  "저장": ["Faylni saqladim.", "Iltimos, saqlash tugmasini bosing.", "Ovqatni uzoq saqlash uchun uni muzlatgichga qo'yib qo'yish kerak.", "Hujjat yozayotgan paytda elektr o'chib qolib, saqlanmagan barcha ma'lumotlar yo'qolib ketdi.", "Qishga tayyorgarlik sifatida kimchini saqlash usullarida har bir hududning o'ziga xos donoligi mujassam.", "Xotira omborining eng chuqur burchagida o'sha kungi manzara rangi o'chgan holda uzoq vaqt uxlab yotardi."],
  "저절로": ["Eshik o'z-o'zidan ochildi.", "Kulgi o'z-o'zidan chiqib ketyapti.", "Ko'chada ketayotib, o'sha qo'shiq o'z-o'zidan esimga tushdi.", "Har qanday qiyin ishni ham muntazam takrorlab borilsa, u o'z-o'zidan odatga aylanib qoladi.", "Yaxshi natija o'z-o'zidan berilmaydi, balki uzoq mehnat evaziga qo'lga kiritiladi.", "Bahor shabadasi esishi bilan mahkam yopilgan qalb zulfini o'z-o'zidan ochilib ketgandek tuyuldi."],
  "저축": ["Men pul tejayman.", "Ozgina jamg'armam bor.", "Har oy maoshning bir qismini jamg'arib borsangiz, katta mablag' to'plashingiz mumkin.", "Aholining jamg'arma darajasi pasaysa, uzoq muddatda bu iqtisodiy o'sishga ham salbiy ta'sir ko'rsatishi mumkin.", "Noaniq keksalik yillariga tayyorgarlik ko'rib, yoshlikdan rejali tarzda jamg'arish zarur.", "U sarflash istagini jilovlab, kunma-kun jamg'argan vaqti oxir-oqibat unga erkinlik hadya etishiga ishonardi."],
  "적극적": ["U faol odam.", "Faolroq gapirib ko'ring.", "Darsda faol savol bersangiz, mavzuni yaxshiroq tushunasiz.", "Suhbatda faol munosabat bilan o'zingizning kuchli tomonlaringizni aniq namoyon qilish muhim.", "Hukumat tug'ilish darajasining pasayishi muammosini hal qilish uchun yanada faolroq qo'llab-quvvatlash siyosatini taklif etishga qaror qildi.", "U loqayd hayot qobig'ini yorib, dunyo sari faol ravishda qadam-baqadam ilgarilab bordi."],
  "적금": ["Men muddatli omonat ochdim.", "Muddatli omonatning foizi qancha?", "To'y xarajatlariga pul yig'ish uchun har oy muddatli omonatga pul qo'yib boryapman.", "Bu bank yoshlar uchun foiz stavkasi yuqori bo'lgan maxsus muddatli omonat mahsulotini yangi taqdim etdi.", "Muddati tugagan jamg'arma omonatini bekor qilmay qayta qo'yilsa, imtiyozli foiz stavkasini olish mumkin.", "O'n yildan ortiq to'lab kelingan muddatli omonat daftarchasida uning halol mehnati ter tomchilari raqamlarga aylanib muhrlangan edi."]
};
